            outline-offset: 2px;
        }
    </style>
</head>
<body>
    <div class="page-content">
        <div class="container">
            <header class="header">
                <h1>My Photo Library</h1>
                <p>Manage your images</p>
            </header>

            <main class="gallery-section">
                <h2>Recent Images</h2>
                <div class="image-grid" id="imageGallery">
                    <!-- Images will be inserted here -->
                </div>
            </main>
        </div>
    </div>

    <!-- Delete confirmation dialog -->
    <dialog id="deleteDialog" aria-labelledby="deleteDialogTitle" aria-describedby="deleteDialogDesc">
        <div class="dialog-content">
            <div class="dialog-icon">⚠️</div>
            <div class="dialog-header">
                <h2 id="deleteDialogTitle">Delete Image?</h2>
            </div>
            <div class="dialog-body" id="deleteDialogDesc">
                <p>Are you sure you want to delete this image? This action cannot be undone.</p>
            </div>
            <div class="dialog-actions">
                <button class="btn btn-cancel" id="cancelBtn" type="button">Cancel</button>
                <button class="btn btn-delete" id="confirmDeleteBtn" type="button">Delete Image</button>
            </div>
        </div>
    </dialog>

    <script>
        // Sample image data
        const images = [
            { id: 1, name: 'Mountain View', date: 'Jan 15, 2025' },
            { id: 2, name: 'Ocean Sunset', date: 'Jan 12, 2025' },
            { id: 3, name: 'Forest Path', date: 'Jan 10, 2025' },
            { id: 4, name: 'City Lights', date: 'Jan 8, 2025' },
            { id: 5, name: 'Desert Dunes', date: 'Jan 5, 2025' },
            { id: 6, name: 'Aurora Borealis', date: 'Jan 1, 2025' },
        ];

        let currentImageId = null;

        // Render gallery
        function renderGallery() {
            const gallery = document.getElementById('imageGallery');
            gallery.innerHTML = images.map(img => `
                <div class="image-card">
                    <div class="image-placeholder">${String.fromCharCode(9733 + (img.id % 5))}</div>
                    <div class="image-info">
                        <div class="image-name">${img.name}</div>
                        <div class="image-date">${img.date}</div>
                        <button class="delete-btn trigger" data-image-id="${img.id}">Delete</button>
                    </div>
                </div>
            `).join('');

            // Attach click handlers to delete buttons
            document.querySelectorAll('.delete-btn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    currentImageId = e.target.dataset.imageId;
                    const dialog = document.getElementById('deleteDialog');
                    dialog.showModal();
                    // Focus on cancel button by default (safe default for destructive action)
                    document.getElementById('cancelBtn').focus();
                });
            });
        }

        // Dialog handlers
        const dialog = document.getElementById('deleteDialog');
        const cancelBtn = document.getElementById('cancelBtn');
        const confirmDeleteBtn = document.getElementById('confirmDeleteBtn');

        // Handle cancel
        cancelBtn.addEventListener('click', () => {
            dialog.close('cancel');
        });

        // Handle confirm delete
        confirmDeleteBtn.addEventListener('click', () => {
            dialog.close('delete');
        });

        // Handle Escape key (browser handles this automatically with <dialog>)
        dialog.addEventListener('close', () => {
            if (dialog.returnValue === 'delete' && currentImageId) {
                const index = images.findIndex(img => img.id === parseInt(currentImageId));
                if (index > -1) {
                    images.splice(index, 1);
                    renderGallery();
                }
            }
            currentImageId = null;
        });

        // Initial render
        renderGallery();
    </script>
</body>
</html>
